import fs from 'node:fs';
const root = new URL('../packages/core/', import.meta.url);
const directory = new URL('migrations/', root);
const migrations = fs
  .readdirSync(directory)
  .filter((name) => name.endsWith('.sql'))
  .sort()
  .map((name) => ({
    name,
    sql: fs.readFileSync(new URL(name, directory), 'utf8').replace(/\r\n/g, '\n'),
  }));
const output =
  '// Generated by scripts/bundle-migrations.js; edit the SQL source files.\nexport interface MigrationRecord { name: string; sql: string }\nexport const MIGRATIONS: readonly MigrationRecord[] = ' +
  JSON.stringify(migrations, null, 2) +
  ';\n';
fs.writeFileSync(new URL('src/migrations/data.ts', root), output);
